export function createCourseUnitsUI({e,api,ui,link,filesView}){
 const localTime=iso=>iso?new Date(Date.parse(iso)+5*3600000).toISOString().slice(0,16):'';
 function editor(classId,units,u={}){return '<form data-vle="unit-save"><input type="hidden" name="classId" value="'+e(classId)+'"><input type="hidden" name="id" value="'+e(u.id||'')+'"><input type="hidden" name="expectedRevision" value="'+(u.revision||0)+'"><div class="vle-form-grid"><label class="vle-field">Unit title<input name="title" maxlength="160" value="'+e(u.title||'')+'" required></label><label class="vle-field">Position<input name="order" type="number" min="1" max="1000" value="'+(u.order||units.length+1)+'" required></label></div><label class="vle-field">Introduction / learning material<textarea name="description" maxlength="10000">'+e(u.description||'')+'</textarea></label><details><summary>Release & prerequisites (optional)</summary><div class="vle-form-grid"><label class="vle-field">Release on (school time)<input type="datetime-local" name="releaseAt" value="'+localTime(u.releaseAt)+'"></label><label class="vle-field">Complete this unit first<select name="prerequisiteId"><option value="">No prerequisite</option>'+units.filter(x=>x.id!==u.id).map(x=>'<option value="'+e(x.id)+'" '+(x.id===u.prerequisiteId?'selected':'')+'>'+e(x.title)+'</option>').join('')+'</select></label></div></details><label class="vle-field">Learning files (optional, up to 3 × 1 MB)<input type="file" name="uploads" multiple accept=".pdf,.txt,.csv,.docx,.xlsx,.pptx,.png,.jpg,.jpeg,.webp"></label><div class="vle-actions"><button type="submit" class="btn primary">'+(u.id?(u.status==='draft'?'Save draft unit':'Save unit'):'Create unit')+'</button></div></form>';}
 function page(r,staff,selected=''){const id=r.class.id,units=r.units||[];if(selected&&!units.some(u=>u.id===selected))return '<p class="error">This unit is not available in this classroom.</p>';return '<div class="learning-section-title"><h2>Course units</h2><span>'+units.length+' unit'+(units.length===1?'':'s')+'</span>'+link(staff?'Class progress':'My learning path',{view:staff?'progress':'path',classId:id})+'</div>'+(selected?'<p>'+link('← All course units',{class:id,tab:'units'})+'</p>':'')+'<p>Read the material, complete the work and move to the next unit.</p>'+(staff?'<details class="vle-panel"><summary>＋ Add a unit</summary>'+editor(id,units)+'</details>':'')+'<div class="course-unit-list">'+(selected?units.filter(u=>u.id===selected):units).map(u=>'<article class="vle-panel course-unit"><div class="learning-section-title"><h3>'+u.order+'. '+e(u.title)+'</h3><span class="learning-tag">'+(staff?(u.status==='draft'?'Draft unit':'Teaching unit'):u.complete?'✓ Complete':!u.available?'Locked':u.total?u.done+' / '+u.total+' turned in':'Ready to read')+'</span></div>'+(!u.available?'<p class="vle-note">'+e(u.reason)+'</p>':'<p class="vle-prose">'+e(u.description||'')+'</p>'+filesView(u.files))+'<div class="vle-actions">'+(u.available&&(staff||u.total)?link('Open unit work →',{class:id,tab:'classwork',unit:u.id}):'')+(staff?'<a class="btn" href="#/classroom?'+new URLSearchParams({class:id,quizEditor:'new',unit:u.id})+'">Create quiz</a>':u.available&&!u.total&&!u.complete?'<button type="button" class="btn" data-unit-complete="'+e(u.id)+'" data-unit-revision="'+u.revision+'">✓ I have finished this unit</button>':'')+(staff?link('Copy unit',{copyUnit:u.id})+(u.status==='draft'?link('Review & publish',{publishUnit:u.id}):''):'')+'</div>'+(staff?'<details><summary>Edit unit & sequence</summary>'+editor(id,units,u)+'</details>':'')+'</article>').join('')+'</div>'+(units.length?'':'<p class="learning-empty">'+(staff?'Add your first unit, then place assignments and quizzes in it.':'Your teacher has not added course units yet. Classwork is available in its usual tab.')+'</p>');}
 function strip(r,params){if(!r.units?.length)return '';const selected=params.get('unit');return '<nav class="course-unit-strip" aria-label="Choose course unit">'+link('All work',{class:r.class.id,tab:'classwork'})+r.units.map(u=>u.available?link((u.status==='draft'?'Draft · ':'')+u.title,{class:r.class.id,tab:'classwork',unit:u.id}).replace('<a ',selected===u.id?'<a aria-current="page" ':'<a '):'<span title="'+e(u.reason)+'">🔒 '+e(u.title)+'</span>').join('')+'</nav>'+(selected&&r.units.find(u=>u.id===selected)?.available===false?'<p class="vle-note">'+e(r.units.find(u=>u.id===selected).reason)+'</p>':'');}
 function bind(root){root.querySelectorAll('[data-unit-complete]').forEach(b=>b.addEventListener('click',async()=>{b.disabled=true;try{await api('unit-complete',{id:b.dataset.unitComplete,expectedRevision:Number(b.dataset.unitRevision)});ui.render();}catch(error){ui.toast(error.message);b.disabled=false;}}));}
 return{page,strip,bind};
}
